func TestArbValuesAreExactMinorUnits(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var s27 int32 = oatText27(text)
	var s28 int32 = oatText28(text)
	var s29 int32 = oatText29(text)
	var s30 int32 = oatText30(text)
	var s31 int32 = oatText31(text)
	var s13 int32 = oatText13(text)
	var s43 int32 = oatText43(text)
	var s44 int32 = oatText44(text)
	var s45 int32 = oatText45(text)
	var s47 int32 = oatText47(text)
	var meta *port.Cells = port.NewCells()
	port.AssertEq64(emonT, ofmt.FmtValue(text, s27, 5, meta), int64(1230), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s28, 10, meta), int64(-123450), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s29, 9, meta), int64(-123450), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s30, 9, meta), int64(-123450), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s31, 8, meta), int64(1230), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s13, 13, meta), int64(57985811), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s43, 12, meta), int64(123456789), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s44, 4, meta), int64(1), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s45, 5, meta), int64(-1), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq64(emonT, ofmt.FmtValue(text, s47, 6, meta), int64(1230), "exact signed minor units")
	port.AssertEq(emonT, port.CellsAt(meta, 0), 1, "valid amount")
	port.AssertEq(emonT, port.CellsAt(meta, 1), 2, "decimal places are recorded")
}

func TestArbAmbiguousGrammarAndOverflowStayInvalid(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var s3 int32 = oatText3(text)
	var s32 int32 = oatText32(text)
	var s33 int32 = oatText33(text)
	var s34 int32 = oatText34(text)
	var s35 int32 = oatText35(text)
	var meta *port.Cells = port.NewCells()
	ofmt.FmtValue(text, s3, 2, meta)
	port.AssertEq(emonT, port.CellsAt(meta, 0), 0, "invalid syntax or bounded overflow cannot be arithmetic evidence")
	ofmt.FmtValue(text, s32, 4, meta)
	port.AssertEq(emonT, port.CellsAt(meta, 0), 0, "invalid syntax or bounded overflow cannot be arithmetic evidence")
	ofmt.FmtValue(text, s33, 3, meta)
	port.AssertEq(emonT, port.CellsAt(meta, 0), 0, "invalid syntax or bounded overflow cannot be arithmetic evidence")
	ofmt.FmtValue(text, s34, 10, meta)
	port.AssertEq(emonT, port.CellsAt(meta, 0), 0, "invalid syntax or bounded overflow cannot be arithmetic evidence")
	ofmt.FmtValue(text, s35, 19, meta)
	port.AssertEq(emonT, port.CellsAt(meta, 0), 0, "invalid syntax or bounded overflow cannot be arithmetic evidence")
}

func TestArbF08Block(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var s3 int32 = oatText3(text)
	var s1 int32 = oatText1(text)
	var s2 int32 = oatText2(text)
	var s0 int32 = oatText0(text)
	var inc *port.Cells = port.NewCells()
	var candidates *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var work *oarbctx.OaWork = oarbctx.NewOaWork()
	oatInc(inc, s3, 2)
	oatInc(inc, s1, 3)
	oatInc(inc, s2, 3)
	oatCandidate(candidates, 0, s0, 2)
	port.AssertEq(emonT, oarb.OaBlock(text, inc, candidates, 0, 2, 2, out, work), 1, "f08-block guard")
	port.AssertEq(emonT, port.CellsAt(out, 0), 0, "first slot chooses the recorded candidate")
	port.AssertEq(emonT, port.CellsAt(out, 1), -1, "valid second slot stays incumbent")
}

