func TestArbBandNumbersAndTiesAreHeld(emonT *testing.T) {
	port.AssertEq(emonT, oarb.OaBandWord(1, 4, 1, 0), 0, "numbers held even with unanimous agreement")
	port.AssertEq(emonT, oarb.OaBandWord(0, 2, 1, 0), 1, "dictionary word agreed by two views")
	port.AssertEq(emonT, oarb.OaBandWord(0, 3, 0, 0), 1, "three views agree on a lexical form")
	port.AssertEq(emonT, oarb.OaBandWord(0, 3, 1, 1), 0, "tie blocks")
	port.AssertEq(emonT, oarb.OaBandRule(2, 0, 900), 0, "at least three accepted words")
	port.AssertEq(emonT, oarb.OaBandRule(5, 1, 900), 0, "one unagreed lexical word blocks the band")
	port.AssertEq(emonT, oarb.OaBandRule(5, 0, 599), 0, "at least sixty percent coverage")
	port.AssertEq(emonT, oarb.OaBandRule(5, 0, 600), 1, "coverage boundary")
}

func TestArbViewBudgetAndIntegerFactor(emonT *testing.T) {
	port.AssertEq(emonT, oarb.OaViewFactor(7, 36), 5, "seven pixel text gets integer x5")
	port.AssertEq(emonT, oarb.OaViewFactor(1, 36), 6, "upscale cap")
	port.AssertEq(emonT, oarb.OaViewFactor(40, 36), 1, "no downscale")
	port.AssertEq(emonT, oarb.OaViewAllowed(0, 0, 0), 0, "born digital cannot request arbitration")
	port.AssertEq(emonT, oarb.OaViewAllowed(1, 0, 3), 1, "last table view")
	port.AssertEq(emonT, oarb.OaViewAllowed(1, 0, 4), 0, "two tables times two views")
	port.AssertEq(emonT, oarb.OaViewAllowed(1, 1, 11), 1, "last band view")
	port.AssertEq(emonT, oarb.OaViewAllowed(1, 1, 12), 0, "three bands times four views")
	port.AssertEq(emonT, oarb.OaActive(), 0, "forced keep until live population guards pass")
}

